description:
A program uses several libraries. Some are **static** (their code is already inside the `.exe`) and some are **DLLs** (files that must be shipped next to it). Write

```cpp
std::vector<std::string> shipList(const std::string& exe, const std::vector<std::pair<std::string, std::string>>& libraries);
```

Each library is a pair of a file name and its kind, `"static"` or `"dll"`. Return the files to put in the folder you give to users:

- the `.exe` first;
- then every DLL, sorted alphabetically;
- each DLL only once, even if it is listed several times. Windows file names ignore case, so `Audio.dll` and `audio.DLL` are the same file: keep the spelling that came first;
- no static libraries.

```
shipList("game.exe", { {"physics.lib","static"}, {"audio.dll","dll"}, {"Audio.DLL","dll"}, {"fonts.dll","dll"} })
    == { "game.exe", "audio.dll", "fonts.dll" }
```

starter.solution.cpp:
#include <string>
#include <utility>
#include <vector>

std::vector<std::string> shipList(const std::string& exe, const std::vector<std::pair<std::string, std::string>>& libraries)
{
    std::vector<std::string> files{ exe };

    return files;
}

solution.solution.cpp:
#include <algorithm>
#include <cctype>
#include <string>
#include <utility>
#include <vector>

static std::string lower(std::string s)
{
    for (char& c : s) c = static_cast<char>(std::tolower(static_cast<unsigned char>(c)));
    return s;
}

std::vector<std::string> shipList(const std::string& exe, const std::vector<std::pair<std::string, std::string>>& libraries)
{
    std::vector<std::string> dlls;
    std::vector<std::string> seen;
    for (const auto& [name, kind] : libraries)
    {
        if (kind != "dll") continue;
        const std::string key{ lower(name) };
        if (std::find(seen.begin(), seen.end(), key) != seen.end()) continue;
        seen.push_back(key);
        dlls.push_back(name);
    }
    std::sort(dlls.begin(), dlls.end(), [](const std::string& a, const std::string& b) { return lower(a) < lower(b); });
    std::vector<std::string> files{ exe };
    files.insert(files.end(), dlls.begin(), dlls.end());
    return files;
}

unitTests:
using Libs = std::vector<std::pair<std::string, std::string>>;
TEST("the example") { CHECK_EQ(shipList("game.exe", Libs{ {"physics.lib","static"}, {"audio.dll","dll"}, {"Audio.DLL","dll"}, {"fonts.dll","dll"} }), (std::vector<std::string>{ "game.exe", "audio.dll", "fonts.dll" })); }
TEST("only static libraries") { CHECK_EQ(shipList("tool.exe", Libs{ {"zlib.lib","static"} }), (std::vector<std::string>{ "tool.exe" })); }
TEST("sorted") { CHECK_EQ(shipList("a.exe", Libs{ {"zeta.dll","dll"}, {"alpha.dll","dll"}, {"mid.dll","dll"} }), (std::vector<std::string>{ "a.exe", "alpha.dll", "mid.dll", "zeta.dll" })); }
TEST("first spelling wins") { CHECK_EQ(shipList("a.exe", Libs{ {"Net.DLL","dll"}, {"net.dll","dll"} }), (std::vector<std::string>{ "a.exe", "Net.DLL" })); }
TEST("no libraries") { CHECK_EQ(shipList("a.exe", Libs{}), (std::vector<std::string>{ "a.exe" })); }

